#!/usr/bin/env python3
"""Look-at page for the Lottie shelf: every animation twice (own colours and brand colours), one slider, one play button.

    .venv/bin/python tools/lottie_sheet.py

Writes library/lottie/GALLERY.html. Open it from disk (file://); it needs the generated library/lottie/<name>.js wrappers.
"""
from __future__ import annotations

import html, json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DIR = ROOT / "library" / "lottie"
SPAN = 8  # seconds the slider covers; every clip loops inside it

PAGE = """<!doctype html>
<!-- GENERATED by tools/lottie_sheet.py. Never edit. -->
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Lottie shelf</title>
<style>
  body { margin: 0; background: #0B0B10; color: #F5F2EA; font: 14px/1.4 system-ui, sans-serif; }
  header { position: sticky; top: 0; z-index: 2; display: flex; gap: 16px; align-items: center; padding: 12px 24px;
    background: #16161F; border-bottom: 1px solid #2C2C3A; }
  header b { white-space: nowrap; }
  button { background: #FF5B2E; color: #0B0B10; border: 0; border-radius: 6px; padding: 6px 16px; font: inherit; font-weight: 600; cursor: pointer; }
  input[type=range] { flex: 1; accent-color: #FF5B2E; }
  output { min-width: 3.5em; text-align: right; font-variant-numeric: tabular-nums; }
  h2 { margin: 28px 24px 8px; font-size: 16px; text-transform: capitalize; }
  .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; padding: 0 24px; }
  .card { background: #16161F; border: 1px solid #2C2C3A; border-radius: 8px; padding: 10px; }
  .pair { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
  .pair figure { margin: 0; text-align: center; font-size: 11px; color: #77758A; }
  canvas { width: 100%; aspect-ratio: 1; background: #0B0B10; border-radius: 6px; }
  .card h3 { margin: 8px 0 0; font-size: 14px; }
  .card p { margin: 2px 0 0; color: #B4B1BF; font-size: 12px; }
  a { color: #FF9A6B; }
  .err { color: #FF4D5E; font-size: 12px; }
</style>
<header>
  <b>Lottie shelf (__COUNT__)</b>
  <button id="play">Play</button>
  <input id="t" type="range" min="0" max="__SPAN__" step="0.01" value="0" aria-label="Time">
  <output id="out">0.00 s</output>
</header>
__BODY__
<script src="../../_runtime/lib.js"></script>
<script src="../../brands/videofactory/tokens.js"></script>
<script>
Lib.bases.lottie = [''];  // the wrappers sit next to this page
const SPAN = __SPAN__, cells = [];
for (const cv of document.querySelectorAll('canvas[data-name]')) {
  const clip = Lib.lottie(cv.dataset.name, cv.dataset.colors ? { colors: cv.dataset.colors } : {});
  cv.width = cv.height = 300;
  cells.push({ cv, clip, ctx: cv.getContext('2d') });
  clip.whenReady.then(draw, (e) => { const m = document.createElement('div'); m.className = 'err'; m.textContent = e.message; cv.replaceWith(m); });
}
let t = 0, playing = false, last = 0;
const slider = document.getElementById('t'), out = document.getElementById('out'), btn = document.getElementById('play');
function draw() {
  out.textContent = t.toFixed(2) + ' s';
  slider.value = t;
  for (const c of cells) {
    if (!c.clip.ready) continue;
    c.ctx.clearRect(0, 0, 300, 300);
    c.clip.at(c.ctx, t, 150, 150, 300, 300, { loop: true });
  }
}
function tick(now) {
  if (!playing) return;
  t = (t + (now - last) / 1000) % SPAN; last = now;
  draw(); requestAnimationFrame(tick);
}
slider.oninput = () => { t = +slider.value; draw(); };
btn.onclick = () => {
  playing = !playing; btn.textContent = playing ? 'Pause' : 'Play';
  if (playing) { last = performance.now(); requestAnimationFrame(tick); }
};
</script>
</html>
"""


def card(name: str, meta: dict) -> str:
    e = lambda k: html.escape(str(meta.get(k) or ""), quote=True)  # noqa: E731
    page = e("page")
    link = f'<a href="{page}" target="_blank" rel="noopener">{e("creator") or "page"}</a>' if page else e("creator")
    return (f'<div class="card"><div class="pair">'
            f'<figure><canvas data-name="{html.escape(name, quote=True)}"></canvas>own colours</figure>'
            f'<figure><canvas data-name="{html.escape(name, quote=True)}" data-colors="brand"></canvas>brand colours</figure>'
            f'</div><h3>{e("title") or html.escape(name)}</h3>'
            f'<p><code>{html.escape(name)}</code> &middot; {e("group")}</p><p>by {link}</p></div>')


def build() -> Path:
    items = []
    for m in sorted(DIR.glob("*.meta.json")):
        name = m.name[: -len(".meta.json")]
        if (DIR / f"{name}.js").exists():
            items.append((name, json.loads(m.read_text(encoding="utf-8"))))
    items.sort(key=lambda it: (it[1].get("group") or "", it[0]))
    body, group = [], None
    for name, meta in items:
        if meta.get("group") != group:
            if group is not None or body:
                body.append("</div>")
            group = meta.get("group")
            body.append(f"<h2>{html.escape(group or 'other')}</h2><div class=\"grid\">")
        body.append(card(name, meta))
    if body:
        body.append("</div>")
    out = DIR / "GALLERY.html"
    out.write_text(PAGE.replace("__COUNT__", str(len(items))).replace("__SPAN__", str(SPAN)).replace("__BODY__", "\n".join(body)),
                   encoding="utf-8")
    return out


if __name__ == "__main__":
    print(build())
